D[95064]={"^Spins around throwing off bolts of lightning at random enemy targets%. Each bolt deals (.-) Nature damage%.%s*$","Gira e cospe descargas de relâmpagos a alvos inimigos aleatórios. Cada descarga causa {{1}} de dano de Natureza."}
D[95066]={"^You hurl molten lava at the target, dealing (.-) Fire damage%.%s*$","Lança lava fundida o alvo, causando {{1}} de dano de Fogo."}
D[95067]={"^Leap through the air%.%s*$","Salta no ar."}
D[95068]={"^Heals an ally for (.-) every (.-) sec%. for (.-)%.%s*$","Cura um aliado {{1}} a cada {{2}} s durante {{3}}."}
