D[95319]={"^Right Click to plant your Exodar banner%.%s*$","Clique com o botão direito do mouse para clavar seu estandarte do Exodar."}
D[95320]={"^Right Click to plant your Gnomeregan banner%.%s*$","Clique com o botão direito do mouse para clavar seu estandarte de Gnomeregan."}
D[95321]={"^Right Click to plant your Orgrimmar banner%.%s*$","Clique com o botão direito do mouse para clavar seu estandarte de Orgrimmar."}
D[95322]={"^Right Click to plant your Undercity banner%.%s*$","Clique com o botão direito do mouse para clavar seu estandarte de Entranhas."}
D[95323]={"^Right Click to plant your Silvermoon City banner%.%s*$","Clique com o botão direito do mouse para clavar seu estandarte dá Cidade Luaprata."}
