D[95914]={"^Causes (.-) Shadow damage over (.-) to your target%.%s*$","Causa {{1}} de dano de Sombra durante {{2}} ao alvo."}
D[95915]={"^Summons a winterfin playmate for Roo%.%s*$","Evoca um companheiro de jogos Falésia Invernal de Lito."}
D[95916]={"^Summons a Snowfall Glade Playmate for Kekek%.%s*$","Evoca um companheiro de jogos Claro Avalanche para Kekeké."}
